/**
 * TASK: Plug your own class into the Java class hierarchy by implementing
 * Iterable<Integer>, so a NumberBag works in an enhanced for loop.
 *
 * NumberBag stores an int[]. iterator() must return a FRESH Iterator<Integer>
 * each time it is called, so the bag can be looped over again and again.
 *
 * The iterator needs exactly two behaviours:
 *   hasNext() -- true while values are left
 *   next()    -- returns the next value, and throws
 *                java.util.NoSuchElementException once the bag is exhausted
 *
 * Example:
 *   NumberBag bag = new NumberBag(3, 1, 4);
 *   int sum = 0;
 *   for (int n : bag) { sum += n; }   // sum -> 8
 *   for (int n : bag) { sum += n; }   // sum -> 16 (a second pass works too)
 */
public class NumberBag implements Iterable<Integer> {

    private final int[] values;

    public NumberBag(int... values) {
        this.values = values;
    }

    public int size() {
        return values.length;
    }

    @Override
    public java.util.Iterator<Integer> iterator() {
        // TODO: return a new Iterator<Integer> that walks the values array.
        // An anonymous class with its own private index field works well here.
        return null;
    }
}

