import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

public class NumberBagTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void fail(String label, Throwable t) {
        System.out.println("FAIL  " + label + " -- expected no error but got "
                + t.getClass().getSimpleName());
        failures++;
    }

    static Integer sumOf(NumberBag bag) {
        int sum = 0;
        for (int n : bag) {
            sum += n;
        }
        return sum;
    }

    public static void main(String[] args) {
        NumberBag bag = new NumberBag(3, 1, 4, 1, 5);

        try {
            check("iterator() is not null", true, bag.iterator() != null);
        } catch (Throwable t) {
            fail("iterator() is not null", t);
        }

        try {
            check("first pass sums to 14", 14, sumOf(bag));
            check("second pass sums to 14 again", 14, sumOf(bag));
        } catch (Throwable t) {
            fail("enhanced for loop over the bag", t);
        }

        try {
            List<Integer> collected = new ArrayList<>();
            for (Integer n : bag) {
                collected.add(n);
            }
            check("values in order", "[3, 1, 4, 1, 5]", collected.toString());
        } catch (Throwable t) {
            fail("values in order", t);
        }

        try {
            Iterator<Integer> one = bag.iterator();
            Iterator<Integer> two = bag.iterator();
            one.next();
            one.next();
            check("iterators are independent", 3, two.next());
        } catch (Throwable t) {
            fail("iterators are independent", t);
        }

        try {
            NumberBag empty = new NumberBag();
            check("empty bag sums to 0", 0, sumOf(empty));
            Iterator<Integer> it = empty.iterator();
            check("empty bag hasNext()", false, it.hasNext());
        } catch (Throwable t) {
            fail("empty bag", t);
        }

        try {
            Iterator<Integer> it = new NumberBag(7).iterator();
            it.next();
            it.next();
            System.out.println("FAIL  next() past the end -- expected NoSuchElementException but nothing was thrown");
            failures++;
        } catch (java.util.NoSuchElementException e) {
            System.out.println("PASS  next() past the end throws NoSuchElementException");
        } catch (Throwable t) {
            System.out.println("FAIL  next() past the end -- expected NoSuchElementException but got "
                    + t.getClass().getSimpleName());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

